import{_ as o,l as s,o as e,c as l,v as r,p as n,x as t,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"移位与桶形移位","description":"","frontmatter":{"title":"移位与桶形移位","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/barrel-shifter.md","filePath":"cs/barrel-shifter.md","lastUpdated":1789023840000}'),p={name:"cs/barrel-shifter.md"};function E(_,a,f,m,A,u){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="移位与桶形移位" tabindex="-1">移位与桶形移位 <a class="header-anchor" href="#移位与桶形移位" aria-label="Permalink to &quot;移位与桶形移位&quot;">​</a></h1><div class="epigraph"><p>移 $k$ 位可以串 $k$ 个一位移位器，也可以用对数级 MUX 一次选出；后者叫桶形，延迟按选择层数算。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/array-multiplier">阵列乘法</a>用「左移再加」描述部分积，但移位本身还不是一块有名字的组合电路。本课不重铺部分积，也不从 RV32I 的 <code>sll</code> 编码另起。缺口是：<strong>任意移位量</strong>如何在一级组合里完成，供后课 ALU 接线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逻辑左移、逻辑右移、算术右移（复制符号）语义已在<a href="/cs/twos-complement">补码</a>与乘法课出现。缺口是实现：一位移位器是接线加 MUX；要移 \\(0..n-1\\)，串行 \\(n\\) 级则延迟 \\(\\Theta(n)\\)。桶形移位器：第 \\(i\\) 层按移位量的第 \\(i\\) 位选择「移 \\(2^i\\) 或 0」，深度 \\(\\Theta(\\log n)\\)，面积 \\(\\Theta(n\\log n)\\) 个 MUX。</p><p>循环移位、漏斗移位点到为止。本课钉桶形作为 ALU 家族的第三块（加、逻辑、移）。</p><h3 id="桶形不是「异步提前执行移位指令」" tabindex="-1">桶形不是「异步提前执行移位指令」 <a class="header-anchor" href="#桶形不是「异步提前执行移位指令」" aria-label="Permalink to &quot;桶形不是「异步提前执行移位指令」&quot;">​</a></h3><p>名字里的 barrel 指交叉开关/多层 MUX，仍是同一组合云。与<a href="/cs/adder-cla">CLA</a>一样，不要理解成流水线超前。移位量来自指令立即数或寄存器低位，本课不译码 opcode。</p><p><span class="marginnote">Harris 画 log 级 MUX 树。Patterson/Hennessy 的 ALU 含移位。<code>srl</code>/<code>sra</code> 差在空位填 0 还是填符号，只改最高位那一路的数据源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据 \\(n\\) 位、量 \\(k=\\lceil\\log_2 n\\rceil\\) 位。层 \\(i\\)：MUX 选原值或右（左）移 \\(2^i\\) 后的值，空位按逻辑/算术规则填。三态/传输门也可搭交叉阵，延迟模型仍按<a href="/cs/critical-path">关键路径</a>。</p>',11)),(e(),n(h,null,{default:t(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%95%B0%E6%8D%AE%E4%B8%8E%E7%A7%BB%E4%BD%8D%E9%87%8F%22%5D%20--%3E%20L0%5B%22MUX%20%E5%B1%82%EF%BC%9A%E7%A7%BB%201%20%E6%88%96%200%22%5D%0A%20%20L0%20--%3E%20L1%5B%22MUX%20%E5%B1%82%EF%BC%9A%E7%A7%BB%202%20%E6%88%96%200%22%5D%0A%20%20L1%20--%3E%20LN%5B%22%E7%9B%B4%E8%87%B3%202%5E%7Bk-1%7D%22%5D%0A%20%20LN%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AALU%20%E7%BB%93%E6%9E%9C%20MUX%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 ALU 把移位器输出送进结果 MUX，与加减、逻辑并列。关键路径可能被桶形或 CLA 主导，设计时要比，不能默认「移位免费」。多周期可用一位移位器加计数器，面积小、CPI 随 \\(k\\) 涨——与乘法的两种实现同一权衡。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 SIMD 跨通道 shuffle、不把浮点对阶移位当同一块规范。旋转与漏斗是桶形的接线变体，不单开课。</p><p>后课默认：任意移位量可用 \\(\\log n\\) 级 MUX 组合完成；ALU 含这一口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一位串移延迟线性；桶形用对数级 MUX。</li><li>逻辑/算术右移只差空位填充。</li><li>仍是组合，计入 ALU 关键路径。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const U=o(p,[["render",E]]);export{b as __pageData,U as default};
